const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Punjab and Haryana region (approximate bounding box)
  const punjabHaryana = ee.Geometry.Polygon([
    [[73.5, 28.5], [77.5, 28.5], [77.5, 32.0], [73.5, 32.0], [73.5, 28.5]]
  ]);

  // Function to count fire detections for a given year
  function countFires(year) {
    const startDate = ee.Date.fromYMD(year, 1, 1);
    const endDate = ee.Date.fromYMD(year, 12, 31);

    // Use MODIS Thermal Anomalies/Fire 8-Day product
    const fires = ee.ImageCollection('MODIS/061/MOD14A2')
      .filterDate(startDate, endDate)
      .filterBounds(punjabHaryana)
      .select('FireMask');

    const imageCount = fires.size().getInfo();

    if (imageCount === 0) {
      return { year: year, count: 0, images: 0, valid: false };
    }

    // FireMask: 7-9 are fire pixels (7=low, 8=nominal, 9=high confidence)
    const fireMask = fires.map(function(img) {
      return img.gte(7);
    }).sum();

    const fireCount = fireMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: punjabHaryana,
      scale: 1000,
      maxPixels: 1e9
    }).get('FireMask');

    const count = fireCount.getInfo();

    return { 
      year: year, 
      count: count !== null ? count : 0, 
      images: imageCount,
      valid: count !== null
    };
  }

  // Analyze all years from 2012 to 2024
  console.log("Counting fire detections for Punjab & Haryana (2012-2024)...");

  const years = [2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, 2023, 2024];
  const results = [];

  for (let year of years) {
    const result = countFires(year);
    results.push(result);
    console.log(`${year}: Fires=${result.count}, Images=${result.images}`);
  }

  // Check if all years returned valid data
  const validResults = results.filter(r => r.valid && r.images > 0);

  if (validResults.length === 0) {
    console.log("No valid fire data found for any year.");
    console.log("<answer>C1</answer>");
    return;
  }

  if (validResults.length < years.length) {
    console.log(`Warning: Only ${validResults.length}/${years.length} years have valid data.`);
  }

  // Find year with maximum fire count
  const maxResult = validResults.reduce((max, r) => r.count > max.count ? r : max);

  console.log(`\nMaximum fires: ${maxResult.count} in ${maxResult.year}`);

  // Check if 2016 has the most fires
  const result2016 = results.find(r => r.year === 2016);

  if (!result2016 || !result2016.valid) {
    console.log("2016 data is invalid or missing.");
    console.log("<answer>C1</answer>");
    return;
  }

  if (result2016.count === maxResult.count && maxResult.year === 2016) {
    console.log("2016 had the most fire detections.");
    console.log("<answer>A</answer>");
  } else {
    console.log("2016 did NOT have the most fire detections.");
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
